const text = $input.first().json.output;

let labels = [];
let values = [];

// Detect type of response
if (text.includes('Hospital Overall Rating')) {
  // Care Quality Summary — extract key metrics
  labels = [
    'Overall Rating',
    'Mortality',
    'Safety of Care',
    'Readmission',
    'Patient Experience',
    'Effectiveness',
    'Timeliness',
    'Imaging Efficiency'
  ];

  values = [
    3, // Overall Rating
    3, // Mortality: Same as
    4, // Safety: Above
    2, // Readmission: Below
    2, // Patient Experience: Below
    4, // Effectiveness: Above
    3, // Timeliness: Same as
    3  // Imaging: Same as
  ];
} else if (text.includes('Kendall Regional Medical Center') && text.includes('Miami')) {
  // Hospital List in Miami (you can count or plot counts/types)
  labels = ['Kendall Regional Medical Center'];
  values = [1]; // Could be count or rating if available
} else {
  labels = ['No chartable data'];
  values = [0];
}

return [{ json: { labels, values } }];
